// Checking a static type after compilation:
var result = engine.Compile("1 + 2");
var staticType = result.AnalyzedExpression?.StaticType;
// staticType.ItemType == ItemType.Integer, staticType.Occurrence == Occurrence.ExactlyOne

var engine = new QueryEngine();
await foreach (var item in engine.ExecuteAsync("1 + 2"))
{
    Console.WriteLine(item); // 3
}

var engine = new QueryEngine(nodeProvider: myNodeProvider);
var compiled = engine.Compile("//book[price > 30]");
if (!compiled.Success)
    throw new InvalidOperationException(string.Join("; ", compiled.Errors.Select(e => e.Message)));

var books = await engine.ExecuteToListAsync(compiled.AnalyzedExpression!, myContainer);

var resolver = new MyDocumentResolver();
var engine = new QueryEngine(documentResolver: resolver);

var result = await engine.ExecuteScalarAsync(
    engine.Compile("count(doc('orders.xml')//order[customer = doc('customers.xml')//customer/@id])").AnalyzedExpression!);

var options = new CompilationOptions
{
    DefaultContainer = myContainer,
    StrictTypeChecking = true
};
var result = engine.Compile("//book[price > 30]", options);

var result = engine.Compile("//book[price > 30]");
if (result.Success)
{
    Console.WriteLine($"Plan: {result.ExecutionPlan}");
    await foreach (var item in engine.ExecuteAsync(result.ExecutionPlan!))
        Console.WriteLine(item);
}
else
{
    foreach (var error in result.Errors)
        Console.Error.WriteLine(error.Message);
}

member.summary:
fn:random-number-generator() as map(xs:string, item())
fn:random-number-generator($seed as xs:anyAtomicType?) as map(xs:string, item())
Returns a map with keys: "number" (random double), "next" (function returning next RNG map),
"permute" (function that randomly permutes a sequence).

Compares two numeric values using XQuery type promotion rules:
decimal+decimal → compare as decimal; double+anything → compare as double;
float+{decimal,integer} → compare as float; decimal+integer → compare as decimal.

fn:iterate-while($seed as item()*, $fn as function(item()*) as item()*,
                 $pred as function(item()*) as xs:boolean) as item()*
Iteratively applies fn while pred returns true (XPath 4.0).

fn:divide-decimals($dividend as xs:decimal, $divisor as xs:decimal,
                   $scale as xs:integer) as xs:decimal
Decimal division with explicit scale (XPath 4.0).

example.code:
public class FileDocumentResolver : IDocumentResolver
{
    public XdmDocument? ResolveDocument(string uri)
    {
        if (!File.Exists(uri)) return null;
        return XdmDocument.Load(File.OpenRead(uri));
    }

    public bool IsDocumentAvailable(string uri) => File.Exists(uri);

    public IEnumerable<XdmNode> ResolveCollection(string? uri)
    {
        var dir = uri ?? "default-collection";
        return Directory.GetFiles(dir, "*.xml").Select(f => ResolveDocument(f)!);
    }
}

// Simple in-memory node provider:
var provider = new DelegateNodeProvider(id => nodeCache.TryGetValue(id, out var node) ? node : null);
var engine = new QueryEngine(nodeProvider: provider);

// Default — XsdSchemaProvider auto-registered, no schemas loaded yet.
var engine = new QueryEngine(nodeProvider: store, documentResolver: store);

// Pre-load schemas via the default provider:
var xsd = new XsdSchemaProvider("catalog.xsd");
var engine2 = new QueryEngine(nodeProvider: store, documentResolver: store, schemaProvider: xsd);

// Custom implementation:
var engine3 = new QueryEngine(nodeProvider: store, documentResolver: store, schemaProvider: new MyRelaxNgProvider());

member.remarks:
Both estimates are heuristics, not contracts. The cost number is unit-less —
only relative ordering matters. Cardinality is a long; 
indicates "unknown / unbounded" and the cost model treats it as infinite.

